/**
 * AnalysisPanel — three category-specific AI report layouts.
 *
 * Frequent Event  → Root Cause · Key Contributing Factors · Infrastructure Solutions · Prevention Strategies
 * Rare Event      → Impact Chains · Immediate Response · Preventive Interventions · Resource Requirements
 * Predictive      → Future Risk Forecast · Possible Event Cascades · Time to Impact · Preventive Recommendations
 */

// ── Shared primitives ─────────────────────────────────────────────────────

function Card({ icon, title, accent, delay = 0, children, fullWidth }) {
  return (
    <div style={{
      background: "#070E1C",
      border: `1px solid ${accent}28`,
      borderRadius: 12,
      overflow: "hidden",
      gridColumn: fullWidth ? "1 / -1" : undefined,
      animation: `fadeUp 0.45s ease ${delay}ms both`,
      boxShadow: `0 0 24px ${accent}07, inset 0 1px 0 ${accent}0C`,
    }}>
      <div style={{
        padding: "11px 19px",
        borderBottom: `1px solid ${accent}18`,
        display: "flex", alignItems: "center", gap: 9,
        background: `linear-gradient(90deg, ${accent}0C, transparent)`,
      }}>
        <span style={{ fontSize: 14 }}>{icon}</span>
        <span style={{
          fontSize: 10, fontWeight: 700, letterSpacing: "0.16em",
          color: accent, textTransform: "uppercase",
        }}>
          {title}
        </span>
      </div>
      <div style={{ padding: "16px 19px" }}>
        {children}
      </div>
    </div>
  );
}

function Paragraph({ text }) {
  return (
    <p style={{ margin: 0, fontSize: 13.5, color: "#CBD5E1", lineHeight: 1.78 }}>
      {text || "—"}
    </p>
  );
}

function NumberedList({ items, accent }) {
  if (!items?.length) return <p style={{ fontSize: 12, color: "#2D4A6B", fontStyle: "italic" }}>No data.</p>;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      {items.map((item, i) => (
        <div key={i} style={{
          display: "flex", gap: 12, alignItems: "flex-start",
          padding: "10px 14px",
          background: `${accent}07`,
          border: `1px solid ${accent}15`,
          borderRadius: 8,
        }}>
          <span style={{
            flexShrink: 0, width: 22, height: 22, borderRadius: "50%",
            border: `1.5px solid ${accent}50`,
            background: `${accent}15`,
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 9, fontWeight: 700, color: accent, marginTop: 1,
          }}>
            {i + 1}
          </span>
          <p style={{ margin: 0, fontSize: 13.5, color: "#CBD5E1", lineHeight: 1.65, paddingTop: 1 }}>
            {item}
          </p>
        </div>
      ))}
    </div>
  );
}

function BulletList({ items, accent, dotColor }) {
  const dot = dotColor || accent;
  if (!items?.length) return null;
  return (
    <ul style={{ margin: 0, padding: 0, listStyle: "none", display: "flex", flexDirection: "column", gap: 8 }}>
      {items.map((item, i) => (
        <li key={i} style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
          <span style={{
            flexShrink: 0, width: 6, height: 6, borderRadius: "50%",
            background: dot, boxShadow: `0 0 5px ${dot}80`,
            marginTop: 7,
          }} />
          <p style={{ margin: 0, fontSize: 13.5, color: "#94A3B8", lineHeight: 1.65 }}>{item}</p>
        </li>
      ))}
    </ul>
  );
}

function MetaBadge({ label, value, color }) {
  return (
    <div style={{
      background: "#070E1C",
      border: `1px solid ${color}25`,
      borderRadius: 9,
      padding: "12px 16px",
      boxShadow: `inset 0 0 14px ${color}07`,
    }}>
      <p style={{ margin: "0 0 5px", fontSize: 9, fontWeight: 700, letterSpacing: "0.14em", color: "#2D4A6B", textTransform: "uppercase" }}>
        {label}
      </p>
      <p style={{ margin: 0, fontSize: 14, fontWeight: 700, color, lineHeight: 1.3 }}>
        {value}
      </p>
    </div>
  );
}

// ── Frequent Event Layout ─────────────────────────────────────────────────

function FrequentReport({ result, color }) {
  const PRIORITY_COLORS = { high: "#EF4444", medium: "#F59E0B", low: "#22C55E" };
  const priorityColor   = PRIORITY_COLORS[result.priority] || color;

  return (
    <>
      {/* Meta row */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 16 }}>
        <MetaBadge label="Event Category"    value="Frequent Event"         color={color} />
        <MetaBadge label="Priority Level"    value={(result.priority || "High").toUpperCase()} color={priorityColor} />
        <MetaBadge label="Analysis Engine"   value="Gemini 1.5 Flash"       color="#22D3EE" />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
        {/* Root Cause — full width */}
        <Card icon="🔍" title="Root Cause" accent={color} delay={0} fullWidth>
          <Paragraph text={result.rootCause} />
        </Card>

        {/* Key Contributing Factors */}
        <Card icon="⚙️" title="Key Contributing Factors" accent={color} delay={60}>
          <BulletList items={result.keyContributingFactors} accent={color} />
        </Card>

        {/* Prevention Strategies */}
        <Card icon="🛡" title="Prevention Strategies" accent={color} delay={120}>
          <BulletList items={result.preventionStrategies} accent={color} dotColor="#22C55E" />
        </Card>

        {/* Infrastructure Solutions — full width */}
        <Card icon="🏗" title="Infrastructure Solutions" accent={color} delay={180} fullWidth>
          <NumberedList items={result.infrastructureSolutions} accent={color} />
        </Card>

        {/* Estimated Impact — full width */}
        {result.estimatedImpact && (
          <Card icon="📊" title="Estimated Impact if Unresolved" accent={color} delay={240} fullWidth>
            <Paragraph text={result.estimatedImpact} />
          </Card>
        )}
      </div>
    </>
  );
}

// ── Rare Event Layout ────────────────────────────────────────────────────

function RareReport({ result, color }) {
  const SEV_COLORS = { critical: "#EF4444", high: "#F97316", medium: "#F59E0B" };
  const sevColor   = SEV_COLORS[result.severityLevel] || "#EF4444";

  return (
    <>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 16 }}>
        <MetaBadge label="Event Category"     value="Rare / Major Event"  color={color} />
        <MetaBadge label="Severity Level"     value={(result.severityLevel || "CRITICAL").toUpperCase()} color={sevColor} />
        <MetaBadge label="Affected Estimate"  value={result.estimatedAffected || "—"}        color="#22D3EE" />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
        {/* Impact Chains — full width */}
        <Card icon="⛓" title="Cascade Impact Chains" accent={color} delay={0} fullWidth>
          <NumberedList items={result.impactChains} accent={color} />
        </Card>

        {/* Immediate Response */}
        <Card icon="🚨" title="Immediate Crisis Response Actions" accent={sevColor} delay={60}>
          <NumberedList items={result.immediateResponseActions} accent={sevColor} />
        </Card>

        {/* Preventive Interventions */}
        <Card icon="🔒" title="Preventive Interventions" accent="#22C55E" delay={120}>
          <BulletList items={result.preventiveInterventions} accent="#22C55E" dotColor="#22C55E" />
        </Card>

        {/* Resource Requirements — full width */}
        {result.resourceRequirements?.length > 0 && (
          <Card icon="🏛" title="Resource & Agency Requirements" accent={color} delay={180} fullWidth>
            <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
              {result.resourceRequirements.map((r, i) => (
                <span key={i} style={{
                  padding: "8px 14px",
                  background: `${color}10`,
                  border: `1px solid ${color}25`,
                  borderRadius: 7,
                  fontSize: 13, color: "#CBD5E1",
                }}>
                  {r}
                </span>
              ))}
            </div>
          </Card>
        )}
      </div>
    </>
  );
}

// ── Predictive Event Layout ──────────────────────────────────────────────

function PredictiveReport({ result, color }) {
  const RISK_COLORS = { critical: "#EF4444", high: "#F97316", medium: "#F59E0B" };
  const riskColor   = RISK_COLORS[result.riskLevel] || "#F97316";
  const tti         = result.timeToImpact || {};

  return (
    <>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 12, marginBottom: 16 }}>
        <MetaBadge label="Event Category"     value="Predictive Risk Event" color={color} />
        <MetaBadge label="Risk Level"         value={(result.riskLevel || "HIGH").toUpperCase()} color={riskColor} />
        <MetaBadge label="Population at Risk" value={result.populationAtRisk || "—"}            color="#22D3EE" />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
        {/* Future Risk Forecast — full width */}
        <Card icon="🔮" title="Future Risk Forecast" accent={color} delay={0} fullWidth>
          <Paragraph text={result.futureRiskForecast} />
        </Card>

        {/* Time to Impact */}
        <Card icon="⏱" title="Time to Impact" accent={riskColor} delay={60}>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {[
              { phase: "Immediate (1-2 hrs)",  text: tti.immediate,  dot: "#EF4444" },
              { phase: "Short-term (6-12 hrs)", text: tti.shortTerm,  dot: "#F97316" },
              { phase: "Long-term (24-48 hrs)", text: tti.longTerm,   dot: "#F59E0B" },
            ].map(({ phase, text, dot }) => text && (
              <div key={phase}>
                <p style={{ margin: "0 0 4px", fontSize: 9, fontWeight: 700, color: dot, letterSpacing: "0.1em", textTransform: "uppercase" }}>
                  {phase}
                </p>
                <p style={{ margin: 0, fontSize: 13, color: "#94A3B8", lineHeight: 1.6 }}>{text}</p>
              </div>
            ))}
          </div>
        </Card>

        {/* Possible Event Cascades */}
        <Card icon="🌊" title="Possible Event Cascades" accent={color} delay={120}>
          <BulletList items={result.possibleEventCascades} accent={color} />
        </Card>

        {/* Preventive Recommendations — full width */}
        <Card icon="✅" title="Preventive Recommendations — Act Now" accent="#22C55E" delay={180} fullWidth>
          <NumberedList items={result.preventiveRecommendations} accent="#22C55E" />
        </Card>
      </div>
    </>
  );
}

// ── Main export ───────────────────────────────────────────────────────────

export default function AnalysisPanel({ result, category, color }) {
  if (!result) return null;

  // Determine category key
  const catKey =
    result.category === "frequent"  ? "frequent"   :
    result.category === "rare"      ? "rare"        :
    result.category === "predictive"? "predictive"  :
    category?.toLowerCase().includes("frequent")  ? "frequent"   :
    category?.toLowerCase().includes("rare")      ? "rare"        :
    "predictive";

  return (
    <div>
      {catKey === "frequent"   && <FrequentReport   result={result} color={color} />}
      {catKey === "rare"       && <RareReport        result={result} color={color} />}
      {catKey === "predictive" && <PredictiveReport  result={result} color={color} />}
    </div>
  );
}
